CREATE TABLE fanout_rebuild_7 (reader_key String, created_at DateTime64(3, 'UTC'), author_key String, doc_id String, group_id String, version UInt64, deleted UInt8 DEFAULT 0, merge_version UInt64 MATERIALIZED version * 2 + toUInt64(deleted), CONSTRAINT valid_version CHECK (version > 0 AND version <= 9223372036854775807), CONSTRAINT valid_deleted CHECK (deleted IN (0, 1))) ENGINE=ReplacingMergeTree(merge_version) ORDER BY (reader_key, created_at, doc_id, author_key, group_id) SETTINGS index_granularity = 64
